using Microsoft.AspNetCore.Mvc; using RaceDay.Mvc.Services; using RaceDay.Mvc.Models; using System.Text.Json;
namespace RaceDay.Mvc.Controllers;
public class OrganiserController(ApiClient api):Controller {
 private string? Token=>HttpContext.Session.GetString("Token"); private bool Guard()=>Token!=null&&HttpContext.Session.GetString("Role")=="Organiser";
 public async Task<IActionResult> Index(){if(!Guard())return RedirectToAction("Login","Account");var events=await api.Get<JsonElement[]>("api/events/mine",Token);var counts=new List<(JsonElement Event,int Count)>();foreach(var e in events??Array.Empty<JsonElement>()){var id=e.GetProperty("eventId").GetInt32();var rows=await api.Get<JsonElement[]>($"api/events/{id}/enrolments",Token);counts.Add((e,rows?.Length??0));}return View(counts);}
 public IActionResult Create(){if(!Guard())return RedirectToAction("Login","Account");return View(new EventVm());}
 [HttpPost] public async Task<IActionResult> Create(EventVm vm){if(!Guard())return RedirectToAction("Login","Account");if(!ModelState.IsValid)return View(vm);var (ok,body)=await api.Post("api/events",vm,Token);if(!ok){ModelState.AddModelError("",body);return View(vm);}TempData["Message"]="Event created.";return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Edit(int id){if(!Guard())return RedirectToAction("Login","Account");var e=await api.Get<JsonElement>($"api/events/{id}",Token);if(e.ValueKind==JsonValueKind.Undefined)return NotFound();return View(new EventVm{EventId=id,Title=e.GetProperty("title").GetString()??"",Description=e.GetProperty("description").GetString()??"",Location=e.GetProperty("location").GetString()??"",EventDate=e.GetProperty("eventDate").GetDateTime(),EventType=e.GetProperty("eventType").GetString()??"Run"});}
 [HttpPost] public async Task<IActionResult> UploadBanner(int eventId,IFormFile file){if(!Guard())return RedirectToAction("Login","Account");var(ok,body)=await api.Upload($"api/storage/events/{eventId}/banner",file,Token);TempData[ok?"Message":"Error"]=ok?"Event banner uploaded.":body;return RedirectToAction(nameof(Edit),new{id=eventId});}
 [HttpPost] public async Task<IActionResult> Edit(EventVm vm){if(!Guard())return RedirectToAction("Login","Account");var(ok,body)=await api.Put($"api/events/{vm.EventId}",vm,Token);TempData[ok?"Message":"Error"]=ok?"Event updated.":body;return RedirectToAction(nameof(Index));}
 [HttpPost] public async Task<IActionResult> Delete(int id){if(!Guard())return RedirectToAction("Login","Account");var(ok,body)=await api.Delete($"api/events/{id}",Token);TempData[ok?"Message":"Error"]=ok?"Event deleted.":body;return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Enrolments(int id){if(!Guard())return RedirectToAction("Login","Account");ViewBag.EventId=id;ViewBag.Event=await api.Get<JsonElement>($"api/events/{id}",Token);return View(await api.Get<JsonElement[]>($"api/events/{id}/enrolments",Token)??Array.Empty<JsonElement>());}
 [HttpGet] public IActionResult Category(int id)=>View(new CategoryVm{EventId=id});
 [HttpPost] public async Task<IActionResult> Category(CategoryVm vm){if(!Guard())return RedirectToAction("Login","Account");var(ok,body)=await api.Post($"api/events/{vm.EventId}/categories",vm,Token);TempData[ok?"Message":"Error"]=ok?"Category added.":body;return RedirectToAction(nameof(Index));}
 [HttpGet] public async Task<IActionResult> Results(int id){if(!Guard())return RedirectToAction("Login","Account");ViewBag.EventId=id;return View(await api.Get<JsonElement[]>($"api/events/{id}/enrolments",Token)??Array.Empty<JsonElement>());}
 [HttpPost] public async Task<IActionResult> SaveResult(int enrolmentId,long finishTimeMs,int? overallPlacement,int eventId){var(ok,body)=await api.Post("api/results",new{enrolmentId,finishTimeMs,overallPlacement},Token);TempData[ok?"Message":"Error"]=ok?"Result saved.":body;return RedirectToAction(nameof(Results),new{id=eventId});}
}
